import { describe, it, expect, vi, beforeEach } from 'vitest';
import { MissionOrchestrator } from './mission-orchestrator';
import { SandboxManager } from '../../sandbox/src/manager';
import type { SandboxProfile } from '../../sandbox/src/types';

vi.mock('../../sandbox/src/manager');

describe('MissionOrchestrator', () => {
  let orchestrator: MissionOrchestrator;
  let mockSandboxManager: vi.Mocked<SandboxManager>;

  beforeEach(() => {
    mockSandboxManager = new SandboxManager() as vi.Mocked<SandboxManager>;
    orchestrator = new MissionOrchestrator(mockSandboxManager);
  });

  it('mission remains READY until approved', async () => {
    const mission = orchestrator.createMission('m-1');
    expect(mission.state).toBe('READY');

    await orchestrator.processPilotGate('m-1', { decision: 'REJECT', rationale: 'Not safe' });
    
    const updated = orchestrator.getMission('m-1');
    expect(updated?.state).toBe('FAILED');
    expect(updated?.metadata?.rationale).toBe('Not safe');
  });

  it('mission transitions to EXECUTING when approved', async () => {
    const mission = orchestrator.createMission('m-2');
    await orchestrator.processPilotGate('m-2', { decision: 'APPROVE', rationale: 'Looks good' });
    
    const updated = orchestrator.getMission('m-2');
    expect(updated?.state).toBe('EXECUTING');
    expect(updated?.metadata?.rationale).toBe('Looks good');
  });

  it('fails if credits are zero', async () => {
    orchestrator.createMission('m-3');
    await orchestrator.processPilotGate('m-3', { decision: 'APPROVE' });

    const profile: SandboxProfile = {
      runtime: 'gvisor',
      resources: { cpu: '1', memory: '1Gi', timeoutSeconds: 60 }
    };

    await orchestrator.provisionSandbox('m-3', profile, 0, 100);

    const updated = orchestrator.getMission('m-3');
    expect(updated?.state).toBe('FAILED');
    expect(updated?.metadata?.reason).toBe('INSUFFICIENT_FUNDS');
    expect(mockSandboxManager.execute).not.toHaveBeenCalled();
  });

  it('provisions sandbox if credits are sufficient', async () => {
    orchestrator.createMission('m-4');
    await orchestrator.processPilotGate('m-4', { decision: 'APPROVE' });

    const profile: SandboxProfile = {
      runtime: 'gvisor',
      resources: { cpu: '1', memory: '1Gi', timeoutSeconds: 60 }
    };

    mockSandboxManager.execute.mockReturnValue({ success: true, executionHash: 'hash123' });

    await orchestrator.provisionSandbox('m-4', profile, 200, 100);

    const updated = orchestrator.getMission('m-4');
    expect(updated?.state).toBe('EXECUTING'); // remains EXECUTING
    expect(mockSandboxManager.execute).toHaveBeenCalledWith(profile);
  });
});

import { SandboxManager } from "../../sandbox/src/manager";
import { SandboxProfile } from "../../sandbox/src/types";

export interface PilotGate {
  decision: 'APPROVE' | 'REJECT';
  rationale?: string;
}

export type MissionState = 'READY' | 'EXECUTING' | 'FAILED' | 'COMPLETED';

export interface Mission {
  id: string;
  state: MissionState;
  metadata?: {
    rationale?: string;
    reason?: string;
    [key: string]: any;
  };
}

export class MissionOrchestrator {
  private missions: Map<string, Mission> = new Map();
  private sandboxManager: SandboxManager;

  constructor(sandboxManager?: SandboxManager) {
    this.sandboxManager = sandboxManager || new SandboxManager();
  }

  public createMission(id: string): Mission {
    const mission: Mission = { id, state: 'READY', metadata: {} };
    this.missions.set(id, mission);
    return mission;
  }

  public getMission(id: string): Mission | undefined {
    return this.missions.get(id);
  }

  public async processPilotGate(missionId: string, gate: PilotGate): Promise<void> {
    const mission = this.missions.get(missionId);
    if (!mission) throw new Error(`Mission ${missionId} not found`);

    if (mission.state !== 'READY') {
      throw new Error(`Cannot process gate for mission in state ${mission.state}`);
    }

    if (gate.decision === 'APPROVE') {
      mission.state = 'EXECUTING';
    } else {
      mission.state = 'FAILED';
    }

    mission.metadata = mission.metadata || {};
    if (gate.rationale) {
      mission.metadata.rationale = gate.rationale;
    }
  }

  public async provisionSandbox(missionId: string, profile: SandboxProfile, credits: number, requiredCredits: number): Promise<void> {
    const mission = this.missions.get(missionId);
    if (!mission) throw new Error(`Mission ${missionId} not found`);

    if (mission.state !== 'EXECUTING') {
      throw new Error(`Mission must be EXECUTING to provision sandbox`);
    }

    if (credits < requiredCredits) {
      mission.state = 'FAILED';
      mission.metadata = mission.metadata || {};
      mission.metadata.reason = 'INSUFFICIENT_FUNDS';
      return;
    }

    const result = this.sandboxManager.execute(profile);
    if (!result.success) {
      mission.state = 'FAILED';
      mission.metadata = mission.metadata || {};
      mission.metadata.reason = result.error;
    }
  }
}

import * as fs from 'fs';
import * as path from 'path';

export interface ComplexityBudgetReport {
  timestamp: number;
  dependencyCount: number;
  dependencyCeiling: number;
  bundleSizeBytes: Record<string, number>;
  bundleCeilingBytes: number;
  complexityScore: number;
  complexityCeiling: number;
  violations: string[];
}

export interface CardinalityLimit {
  metricName: string;
  allowedLabels: string[];
  maxCardinality: number;
  actualCardinality: number;
}

export class ComplexityBudgetEvaluator {
  private workspaceRoot: string;
  private dependencyCeiling = 75;
  private bundleCeilingBytes = 200 * 1024; // 200 KB
  private complexityCeiling = 60; // Max allowed modules/components

  constructor(workspaceRoot: string) {
    this.workspaceRoot = workspaceRoot;
  }

  /**
   * Evaluates current workspace complexity against strict mechanical limits.
   */
  public evaluate(): ComplexityBudgetReport {
    const violations: string[] = [];
    let dependencyCount = 0;

    // 1. Dependency Ceiling Audit
    const rootPkgPath = path.join(this.workspaceRoot, 'package.json');
    if (fs.existsSync(rootPkgPath)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(rootPkgPath, 'utf8'));
        const deps = Object.keys(pkg.dependencies ?? {});
        dependencyCount = deps.length;
        if (dependencyCount > this.dependencyCeiling) {
          violations.push(
            `DEPENDENCY_CEILING_EXCEEDED: Direct dependencies count ${dependencyCount} exceeds ceiling of ${this.dependencyCeiling}`
          );
        }
      } catch (err) {
        // Safe fallback
      }
    }

    // 2. Bundle Size Gates Audit
    const bundleSizes: Record<string, number> = {};
    const pkgDirs = ['production-pilot', 'core-engine'];
    for (const dir of pkgDirs) {
      const distPath = path.join(this.workspaceRoot, 'packages', dir, 'dist', 'index.js');
      if (fs.existsSync(distPath)) {
        const stats = fs.statSync(distPath);
        bundleSizes[dir] = stats.size;
        if (stats.size > this.bundleCeilingBytes) {
          violations.push(
            `BUNDLE_SIZE_EXCEEDED: Package @packages/${dir} bundle size ${Math.round(
              stats.size / 1024
            )} KB exceeds gate ceiling of ${Math.round(this.bundleCeilingBytes / 1024)} KB`
          );
        }
      } else {
        // Simulated default if build not run yet
        bundleSizes[dir] = 160 * 1024; // 160 KB baseline
      }
    }

    // 3. Operational Complexity Analysis
    // Complexity Score is measured as the count of active source files inside packages/production-pilot/src
    let srcFileCount = 0;
    const srcDir = path.join(this.workspaceRoot, 'packages', 'production-pilot', 'src');
    if (fs.existsSync(srcDir)) {
      try {
        const files = fs.readdirSync(srcDir);
        srcFileCount = files.filter(f => f.endsWith('.ts') && !f.endsWith('.test.ts')).length;
        if (srcFileCount > this.complexityCeiling) {
          violations.push(
            `COMPLEXITY_LIMIT_EXCEEDED: Active source modules count ${srcFileCount} exceeds ceiling of ${this.complexityCeiling}`
          );
        }
      } catch (err) {
        // Safe fallback
      }
    }

    const report: ComplexityBudgetReport = {
      timestamp: Date.now(),
      dependencyCount,
      dependencyCeiling: this.dependencyCeiling,
      bundleSizeBytes: bundleSizes,
      bundleCeilingBytes: this.bundleCeilingBytes,
      complexityScore: srcFileCount,
      complexityCeiling: this.complexityCeiling,
      violations,
    };

    return report;
  }
}

export class TelemetryCardinalityAuditor {
  private limits: CardinalityLimit[] = [];

  constructor() {
    this.registerLimit('ztan_tenant_executions_total', ['tenantId', 'namespace'], 50);
    this.registerLimit('ztan_workflow_duration_seconds', ['workflowId', 'version'], 50);
  }

  public registerLimit(metricName: string, allowedLabels: string[], maxCardinality: number): void {
    this.limits.push({
      metricName,
      allowedLabels,
      maxCardinality,
      actualCardinality: 0,
    });
  }

  /**
   * Assures telemetry cardinality budgets are strictly managed.
   */
  public audit(liveMetrics: Record<string, string[]>): string[] {
    const violations: string[] = [];

    for (const limit of this.limits) {
      const liveLabels = liveMetrics[limit.metricName] ?? [];
      limit.actualCardinality = liveLabels.length;

      if (limit.actualCardinality > limit.maxCardinality) {
        violations.push(
          `CARDINALITY_BUDGET_EXCEEDED: Metric '${limit.metricName}' has unique label values cardinality ${limit.actualCardinality} exceeding budget ceiling of ${limit.maxCardinality}`
        );
      }
    }

    return violations;
  }

  public getLimits(): CardinalityLimit[] {
    return this.limits;
  }
}

import * as fs from 'fs';
import * as path from 'path';

export interface IncidentRecord {
  incidentId: string;
  timestamp: number;
  anomalyFingerprint: string;
  workflowId: string;
  errorStack: string;
  reproductionSteps: string[];
}

export interface RecoveryScoreReport {
  incidentId: string;
  mttrMs: number;
  stepsCount: number;
  ambiguityPoints: number;
  laborEfficiencyIndex: number; // 0.0 to 100.0 (Higher is better)
  rating: 'EXCELLENT' | 'ADEQUATE' | 'INEFFICIENT';
}

export class AnomalyFingerprinter {
  /**
   * Generates a deterministic cryptographic-like hash based on failure patterns.
   */
  static generateFingerprint(stackTrace: string): string {
    if (!stackTrace) return 'GENERIC_UNSPECIFIED_ANOMALY';
    
    // Extract key lines or exception class name from stack trace
    const firstLine = stackTrace.split('\n')[0] ?? '';
    const cleanPattern = firstLine.replace(/[^a-zA-Z0-9_]/g, '_').toUpperCase();
    
    let hash = 0;
    for (let i = 0; i < stackTrace.length; i++) {
      const char = stackTrace.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    
    return `ANOMALY_${cleanPattern}_${Math.abs(hash).toString(16)}`;
  }
}

export class IncidentReplayCatalog {
  private archivePath: string;

  constructor(archivePath: string) {
    this.archivePath = archivePath;
  }

  /**
   * Registers a failed operational execution event in the persistent intelligence store.
   */
  public registerIncident(
    workflowId: string,
    errorStack: string,
    reproductionSteps: string[]
  ): IncidentRecord {
    const fingerprint = AnomalyFingerprinter.generateFingerprint(errorStack);
    const incidentId = `INCIDENT-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;

    const record: IncidentRecord = {
      incidentId,
      timestamp: Date.now(),
      anomalyFingerprint: fingerprint,
      workflowId,
      errorStack,
      reproductionSteps,
    };

    try {
      if (!fs.existsSync(this.archivePath)) {
        fs.mkdirSync(this.archivePath, { recursive: true });
      }
      const file = path.join(this.archivePath, `incident_${incidentId}.json`);
      fs.writeFileSync(file, JSON.stringify(record, null, 2), 'utf8');
    } catch (err) {
      // Safe no-op
    }

    return record;
  }

  public listIncidents(): IncidentRecord[] {
    if (!fs.existsSync(this.archivePath)) return [];
    try {
      const files = fs.readdirSync(this.archivePath);
      return files
        .filter(f => f.startsWith('incident_') && f.endsWith('.json'))
        .map(f => {
          const raw = fs.readFileSync(path.join(this.archivePath, f), 'utf8');
          return JSON.parse(raw);
        });
    } catch (err) {
      return [];
    }
  }
}

export class RecoveryEffectivenessScorer {
  /**
   * Evaluates manual recovery drills against standard labor curves.
   */
  static score(incidentId: string, mttrMs: number, stepsCount: number, ambiguityPoints: number): RecoveryScoreReport {
    // Labor Efficiency Index is scored starting from 100, penalizing long duration and operator confusion:
    const mttrPenalty = Math.min(40, (mttrMs / 60000) * 10); // 10 points per minute of MTTR
    const ambiguityPenalty = ambiguityPoints * 5; // 5 points per confusion event
    const stepsPenalty = Math.max(0, (stepsCount - 4) * 3); // nominal recovery steps count is 4

    const laborEfficiencyIndex = Math.max(0, Math.round(100 - mttrPenalty - ambiguityPenalty - stepsPenalty));

    let rating: RecoveryScoreReport['rating'] = 'EXCELLENT';
    if (laborEfficiencyIndex < 60) {
      rating = 'INEFFICIENT';
    } else if (laborEfficiencyIndex < 85) {
      rating = 'ADEQUATE';
    }

    return {
      incidentId,
      mttrMs,
      stepsCount,
      ambiguityPoints,
      laborEfficiencyIndex,
      rating,
    };
  }
}

export interface LongitudinalTrend {
  status: string;
  determinismRate: number;
  avgSemanticDrift: number;
  isolationIntegrityScore: number;
  resourceEfficiency: number;
  governanceEfficiencyIndex: number;
  complexityFactor: number;
  regressionScore: number;
  driftAcceleration: number;
  survivabilityProjection: number;
}

export class LongitudinalAnalyzer {
  /**
   * Performs longitudinal trend analysis over campaign telemetry packets.
   */
  static analyze(packets: any[], baselinePackets?: any[]): LongitudinalTrend {
    if (!packets || packets.length === 0) {
      return {
        status: 'BORING',
        determinismRate: 1.0,
        avgSemanticDrift: 0.0,
        isolationIntegrityScore: 100,
        resourceEfficiency: 1.0,
        governanceEfficiencyIndex: 100.0,
        complexityFactor: 1.0,
        regressionScore: 100,
        driftAcceleration: 0.0,
        survivabilityProjection: 365,
      };
    }

    // Determinism Rate
    const revertibleCount = packets.filter(p => p.recovery?.revertible !== false).length;
    const determinismRate = revertibleCount / packets.length;

    // Average Semantic Drift
    const avgSemanticDrift = packets.reduce((sum, p) => sum + (p.semanticDrift ?? 0.0), 0) / packets.length;

    // Isolation Integrity Score
    const sandboxCount = packets.filter(p => p.attestation?.isolationLevel === 'sandbox').length;
    const isolationIntegrityScore = Math.round((sandboxCount / packets.length) * 100);

    // Resource Efficiency
    let totalCeiling = 0;
    let totalConsumption = 0;
    for (const p of packets) {
      totalCeiling += p.economics?.costCeiling ?? 10000;
      totalConsumption += p.economics?.tokenConsumption ?? 2000;
    }
    const resourceEfficiency = totalCeiling > 0 
      ? Math.max(0, Math.min(1, (totalCeiling - totalConsumption) / totalCeiling)) 
      : 0.8;

    // Complexity Factor
    let totalKeys = 0;
    for (const p of packets) {
      totalKeys += Object.keys(p.provenance ?? p.attestation ?? {}).length;
    }
    const complexityFactor = 1.0 + (totalKeys / packets.length) * 0.1;

    // Drift Acceleration
    let driftAcceleration = 0.0001;
    if (packets.length >= 2) {
      const firstDrift = packets[0].semanticDrift ?? 0;
      const lastDrift = packets[packets.length - 1].semanticDrift ?? 0;
      driftAcceleration = (lastDrift - firstDrift) / Math.max(1, packets.length - 1);
    }

    // Regression Score
    const regressionScore = LongitudinalAnalyzer.calculateRegressionScore(packets);

    // Governance Efficiency
    const governanceEfficiencyIndex = Math.max(0, Math.min(100, 100 - (complexityFactor - 1) * 20));

    // Survivability Projection
    const absDriftAcceleration = Math.max(0.00001, Math.abs(driftAcceleration));
    const survivabilityProjection = Math.max(1, Math.round(0.3 / absDriftAcceleration));

    // Status Envelope
    let status = 'BORING';
    if (avgSemanticDrift > 0.10 || regressionScore < 85) {
      status = 'REGRESSION_RISK';
    } else if (avgSemanticDrift > 0.05 || regressionScore < 95) {
      status = 'ELEVATED_RISK';
    } else if (complexityFactor > 1.5) {
      status = 'INEFFICIENT_GOVERNANCE';
    }

    return {
      status,
      determinismRate,
      avgSemanticDrift,
      isolationIntegrityScore,
      resourceEfficiency,
      governanceEfficiencyIndex,
      complexityFactor,
      regressionScore,
      driftAcceleration,
      survivabilityProjection,
    };
  }

  /**
   * Calculates the regression score and detects predictive risk based on drift trends (Hidden Risk).
   */
  static calculateRegressionScore(packets: any[]): number {
    if (!packets || packets.length === 0) return 100;
    const avgSemanticDrift = packets.reduce((sum, p) => sum + (p.semanticDrift ?? 0.0), 0) / packets.length;
    
    // Check drift acceleration trend (Hidden Risk)
    let accelerationFactor = 0;
    if (packets.length >= 2) {
      const firstDrift = packets[0].semanticDrift ?? 0;
      const lastDrift = packets[packets.length - 1].semanticDrift ?? 0;
      const driftDelta = lastDrift - firstDrift;
      if (driftDelta > 0) {
        // Positive acceleration means increasing drift, apply penalty
        accelerationFactor = driftDelta * 100;
      }
    }
    
    return Math.max(0, Math.min(100, Math.round(100 - (avgSemanticDrift * 150) - accelerationFactor)));
  }

  /**
   * Calculates consecutive epochs within nominal bounds ("Boring Time").
   */
  static calculateBoringEpochs(packets: any[]): number {
    if (!packets || packets.length === 0) return 0;
    let boringCount = 0;
    for (let i = packets.length - 1; i >= 0; i--) {
      const p = packets[i];
      const drift = p.semanticDrift ?? 0;
      const isRevertible = p.recovery?.revertible !== false;
      const isSandbox = p.attestation?.isolationLevel === 'sandbox';

      if (drift < 0.10 && isRevertible && isSandbox) {
        boringCount++;
      } else {
        break;
      }
    }
    return boringCount;
  }
}

import * as fs from 'fs';
import * as path from 'path';

export type FailureScenarioClass = 'WAL_CORRUPTION' | 'REPLICA_FENCING' | 'DKG_KEY_FAILURE' | 'LEASE_STARVATION';

export interface RecoveryActionRecord {
  timestamp: number;
  actionName: string;
  isAmbiguous: boolean; // True if action is a redundant query or repeated retry
}

export interface OperatorCertificationReport {
  scenario: FailureScenarioClass;
  startTime: number;
  endTime: number;
  mttrMs: number;
  success: boolean;
  actions: RecoveryActionRecord[];
  ambiguityScore: number; // Penalty based on redundant/unproductive actions (0 = perfect)
  reproducibilityRate: number; // 0.0 to 1.0 based on path variance
}

export class OperatorRecoveryCertification {
  private activeScenario?: FailureScenarioClass;
  private startTime: number = 0;
  private actions: RecoveryActionRecord[] = [];
  private reportDir: string;

  constructor(reportDir: string) {
    this.reportDir = reportDir;
  }

  /**
   * Triggers a specific failure scenario and starts the recovery timer.
   */
  public triggerFailure(scenario: FailureScenarioClass): void {
    this.activeScenario = scenario;
    this.startTime = Date.now();
    this.actions = [];
  }

  /**
   * Records an operator action during a recovery drill.
   */
  public recordAction(actionName: string, isAmbiguous: boolean = false): void {
    this.actions.push({
      timestamp: Date.now(),
      actionName,
      isAmbiguous,
    });
  }

  /**
   * Finalizes the recovery drill and compiles the human recovery science metrics.
   */
  public completeRecovery(success: boolean): OperatorCertificationReport {
    if (!this.activeScenario) {
      throw new Error('[SECURITY] No active failure scenario to complete.');
    }

    const endTime = Date.now();
    const mttrMs = endTime - this.startTime;

    // Ambiguity Score calculation:
    // Every ambiguous action penalizes by 10 points. If MTTR is exceptionally long, apply minor time penalty.
    const ambiguousCount = this.actions.filter(a => a.isAmbiguous).length;
    const ambiguityScore = ambiguousCount * 10 + Math.min(50, Math.floor(mttrMs / 10000));

    // Reproducibility Rate:
    // Compares path actions against nominal expected sequence length.
    const expectedLength = 4; // Nominal recovery path actions count
    const actualLength = this.actions.length;
    const reproducibilityRate = Math.max(0, 1 - Math.abs(actualLength - expectedLength) / expectedLength);

    const report: OperatorCertificationReport = {
      scenario: this.activeScenario,
      startTime: this.startTime,
      endTime,
      mttrMs,
      success,
      actions: [...this.actions],
      ambiguityScore,
      reproducibilityRate: parseFloat(reproducibilityRate.toFixed(4)),
    };

    this.saveReport(report);
    this.activeScenario = undefined;

    return report;
  }

  private saveReport(report: OperatorCertificationReport): void {
    try {
      if (!fs.existsSync(this.reportDir)) {
        fs.mkdirSync(this.reportDir, { recursive: true });
      }
      const filepath = path.join(this.reportDir, `operator_drill_${report.scenario}_${Date.now()}.json`);
      fs.writeFileSync(filepath, JSON.stringify(report, null, 2), 'utf8');
    } catch (err) {
      // Safe fallback
    }
  }

  public getActiveScenario(): FailureScenarioClass | undefined {
    return this.activeScenario;
  }
}

import * as fs from 'fs';
import * as path from 'path';

export interface ReplayEventLog {
  workflowId: string;
  sequence: number;
  type: string;
  timestamp: number;
  payload: any;
}

export interface ReplaySession {
  workflowId: string;
  events: ReplayEventLog[];
  executionTimeMs: number;
}

export interface DriftEnvelope {
  reproducibilityRate: number; // 0.0 to 1.0
  driftScore: number;          // 0.0 to 100.0
  varianceMs: number;
  divergenceHotspots: string[];
}

export class HistoricalReplayCorpus {
  private corpusPath: string;
  private corpus: Map<string, ReplaySession> = new Map();

  constructor(corpusPath: string) {
    this.corpusPath = corpusPath;
    this.loadCorpus();
  }

  private loadCorpus(): void {
    try {
      if (fs.existsSync(this.corpusPath)) {
        const raw = fs.readFileSync(this.corpusPath, 'utf8');
        const list: ReplaySession[] = JSON.parse(raw);
        for (const session of list) {
          this.corpus.set(session.workflowId, session);
        }
      }
    } catch (err) {
      // Bounded fallback: if load fails, start with an empty corpus
      this.corpus.clear();
    }
  }

  public saveCorpus(): void {
    try {
      const list = Array.from(this.corpus.values());
      const dir = path.dirname(this.corpusPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      fs.writeFileSync(this.corpusPath, JSON.stringify(list, null, 2), 'utf8');
    } catch (err) {
      // Safe no-op on failure
    }
  }

  public register(session: ReplaySession): void {
    this.corpus.set(session.workflowId, session);
    this.saveCorpus();
  }

  public get(workflowId: string): ReplaySession | undefined {
    return this.corpus.get(workflowId);
  }

  public all(): ReplaySession[] {
    return Array.from(this.corpus.values());
  }
}

export class DriftEnvelopeAnalyzer {
  /**
   * Compares a live sequence against a recorded corpus baseline to detect drift.
   */
  static analyze(live: ReplayEventLog[], baseline: ReplayEventLog[]): { similarity: number; hotspots: string[] } {
    if (live.length === 0 || baseline.length === 0) {
      return { similarity: 0.0, hotspots: ['EMPTY_EVENT_LOG'] };
    }

    let matchCount = 0;
    const hotspots: string[] = [];
    const maxLen = Math.max(live.length, baseline.length);

    for (let i = 0; i < maxLen; i++) {
      const liveEv = live[i];
      const baseEv = baseline[i];

      if (!liveEv) {
        hotspots.push(`MISSING_LIVE_EVENT_AT_SEQ_${i}`);
        continue;
      }
      if (!baseEv) {
        hotspots.push(`EXTRA_LIVE_EVENT_AT_SEQ_${i}_TYPE_${liveEv.type}`);
        continue;
      }

      const typeMatch = liveEv.type === baseEv.type;
      const sequenceMatch = liveEv.sequence === baseEv.sequence;
      const payloadMatch = JSON.stringify(liveEv.payload) === JSON.stringify(baseEv.payload);

      if (typeMatch && sequenceMatch && payloadMatch) {
        matchCount++;
      } else {
        if (!typeMatch) hotspots.push(`EVENT_TYPE_MISMATCH_AT_SEQ_${i}_EXPECTED_${baseEv.type}_GOT_${liveEv.type}`);
        if (!payloadMatch && typeMatch) hotspots.push(`EVENT_PAYLOAD_MISMATCH_AT_SEQ_${i}_TYPE_${liveEv.type}`);
      }
    }

    return {
      similarity: matchCount / maxLen,
      hotspots,
    };
  }
}

export class ReplayVarianceRecorder {
  private timings: Map<string, number[]> = new Map();

  public record(workflowId: string, durationMs: number): void {
    if (!this.timings.has(workflowId)) {
      this.timings.set(workflowId, []);
    }
    this.timings.get(workflowId)!.push(durationMs);
  }

  public getVariance(workflowId: string): number {
    const list = this.timings.get(workflowId) ?? [];
    if (list.length <= 1) return 0;

    const mean = list.reduce((sum, t) => sum + t, 0) / list.length;
    const squaredDiffs = list.map(t => Math.pow(t - mean, 2));
    const variance = squaredDiffs.reduce((sum, d) => sum + d, 0) / list.length;

    return Math.sqrt(variance); // Return standard deviation
  }
}

export class ReplayCertificationHarness {
  private corpus: HistoricalReplayCorpus;
  private varianceRecorder: ReplayVarianceRecorder = new ReplayVarianceRecorder();

  constructor(corpusPath: string) {
    this.corpus = new HistoricalReplayCorpus(corpusPath);
  }

  /**
   * Certifies a workflow replay run against its recorded baseline.
   */
  public certify(liveSession: ReplaySession): DriftEnvelope {
    this.varianceRecorder.record(liveSession.workflowId, liveSession.executionTimeMs);
    const baseline = this.corpus.get(liveSession.workflowId);

    if (!baseline) {
      // First run: Register as baseline and certify with nominal determinism
      this.corpus.register(liveSession);
      return {
        reproducibilityRate: 1.0,
        driftScore: 0.0,
        varianceMs: 0,
        divergenceHotspots: [],
      };
    }

    // Compare live vs. baseline
    const { similarity, hotspots } = DriftEnvelopeAnalyzer.analyze(liveSession.events, baseline.events);
    const variance = this.varianceRecorder.getVariance(liveSession.workflowId);
    
    // Register latest for longitudinal corpus comparison if reproducibility is high
    if (similarity > 0.95) {
      this.corpus.register(liveSession);
    }

    return {
      reproducibilityRate: similarity,
      driftScore: Math.max(0, Math.min(100, Math.round((1.0 - similarity) * 100))),
      varianceMs: Math.round(variance),
      divergenceHotspots: hotspots,
    };
  }

  public getCorpus(): HistoricalReplayCorpus {
    return this.corpus;
  }
}

import * as fs from 'fs';
import * as path from 'path';

export interface ResourceMetricSnapshot {
  timestamp: number;
  heapUsedBytes: number;
  externalMemoryBytes: number;
  rssBytes: number;
  activeTimers: number;
  activeSockets: number;
  openFileHandles: number;
  eventLoopLagMs: number;
}

export interface ResourceScalingReport {
  workflowId: string;
  stepCount: number;
  snapshots: ResourceMetricSnapshot[];
  walAmplificationRatio: number; // WAL written size vs. raw workflow state update size
  telemetryAmplificationRatio: number; // OTEL trace size vs. workflow state size
  memoryPerStepSlopeBytes: number;
  eventLoopLagVarianceMs: number;
  peakRssBytes: number;
}

export class ResourceEnvelopeProfiler {
  private startTime: number = Date.now();
  private snapshots: ResourceMetricSnapshot[] = [];
  private stepCount: number = 0;
  private totalWalBytesWritten: number = 0;
  private totalRawStateBytes: number = 0;
  private totalTelemetryBytes: number = 0;
  
  // Track handles from central registries/scopes
  private activeSockets: number = 0;
  private activeTimers: number = 0;
  private openFileHandles: number = 0;

  constructor() {}

  public start(): void {
    this.startTime = Date.now();
    this.snapshots = [];
    this.stepCount = 0;
    this.totalWalBytesWritten = 0;
    this.totalRawStateBytes = 0;
    this.totalTelemetryBytes = 0;
    this.sample();
  }

  public recordStep(stateSize: number, walSize: number, telemetrySize: number = 0): void {
    this.stepCount++;
    this.totalRawStateBytes += stateSize;
    this.totalWalBytesWritten += walSize;
    this.totalTelemetryBytes += telemetrySize;
    this.sample();
  }

  public updateHandles(timers: number, sockets: number, fileHandles: number): void {
    this.activeTimers = timers;
    this.activeSockets = sockets;
    this.openFileHandles = fileHandles;
  }

  /**
   * Samples V8 memory and calculates loop lag.
   */
  public sample(): void {
    const mem = process.memoryUsage();
    
    // Bounded calculation of event loop lag
    const sampleStart = Date.now();
    let loopLag = 0;
    setImmediate(() => {
      loopLag = Date.now() - sampleStart;
    });

    this.snapshots.push({
      timestamp: Date.now(),
      heapUsedBytes: mem.heapUsed,
      externalMemoryBytes: mem.external ?? 0,
      rssBytes: mem.rss,
      activeTimers: this.activeTimers,
      activeSockets: this.activeSockets,
      openFileHandles: this.openFileHandles,
      eventLoopLagMs: loopLag,
    });
  }

  /**
   * Generates a scaling report mapping empirical resource curves.
   */
  public generateReport(workflowId: string, reportDir?: string): ResourceScalingReport {
    this.sample(); // final sample

    const peakRss = Math.max(...this.snapshots.map(s => s.rssBytes), 0);
    
    // WAL Amplification Ratio: total written WAL bytes vs total raw state updates
    const walAmplification = this.totalRawStateBytes > 0 
      ? this.totalWalBytesWritten / this.totalRawStateBytes 
      : 1.0;

    // Telemetry Amplification: total tracing bytes vs total raw state updates
    const telemetryAmplification = this.totalRawStateBytes > 0 
      ? this.totalTelemetryBytes / this.totalRawStateBytes 
      : 0.1;

    // Calculate memory slope: change in heap usage divided by step count
    let memorySlope = 0;
    if (this.snapshots.length > 1 && this.stepCount > 0) {
      const firstHeap = this.snapshots[0].heapUsedBytes;
      const lastHeap = this.snapshots[this.snapshots.length - 1].heapUsedBytes;
      memorySlope = Math.max(0, (lastHeap - firstHeap) / this.stepCount);
    }

    // Calculate event loop lag variance
    let lagVariance = 0;
    const lags = this.snapshots.map(s => s.eventLoopLagMs);
    if (lags.length > 1) {
      const mean = lags.reduce((sum, l) => sum + l, 0) / lags.length;
      const squaredDiffs = lags.map(l => Math.pow(l - mean, 2));
      lagVariance = squaredDiffs.reduce((sum, d) => sum + d, 0) / lags.length;
    }

    const report: ResourceScalingReport = {
      workflowId,
      stepCount: this.stepCount,
      snapshots: this.snapshots,
      walAmplificationRatio: parseFloat(walAmplification.toFixed(4)),
      telemetryAmplificationRatio: parseFloat(telemetryAmplification.toFixed(4)),
      memoryPerStepSlopeBytes: Math.round(memorySlope),
      eventLoopLagVarianceMs: parseFloat(lagVariance.toFixed(4)),
      peakRssBytes: peakRss,
    };

    if (reportDir) {
      try {
        if (!fs.existsSync(reportDir)) {
          fs.mkdirSync(reportDir, { recursive: true });
        }
        const filepath = path.join(reportDir, `resource_report_${workflowId}.json`);
        fs.writeFileSync(filepath, JSON.stringify(report, null, 2), 'utf8');
      } catch (err) {
        // Safe no-op
      }
    }

    return report;
  }
}
